CREATE OR REPLACE FUNCTION assert_interview_blueprint_complete(target_interview_id text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  expected_count smallint;
  actual_count bigint;
  minimum_position smallint;
  maximum_position smallint;
BEGIN
  SELECT selected_question_count
    INTO expected_count
    FROM interview_sessions
   WHERE id = target_interview_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT count(*), min(position), max(position)
    INTO actual_count, minimum_position, maximum_position
    FROM session_question_snapshots
   WHERE interview_id = target_interview_id;

  IF actual_count <> expected_count
     OR minimum_position <> 1
     OR maximum_position <> expected_count THEN
    RAISE EXCEPTION
      'interview % requires contiguous question positions 1..%, found count %, min %, max %',
      target_interview_id,
      expected_count,
      actual_count,
      minimum_position,
      maximum_position
      USING ERRCODE = '23514',
            CONSTRAINT = 'session_question_snapshots_complete_blueprint_check';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION check_interview_blueprint_from_session()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  PERFORM assert_interview_blueprint_complete(NEW.id);
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION check_interview_blueprint_from_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM assert_interview_blueprint_complete(OLD.interview_id);
  ELSE
    PERFORM assert_interview_blueprint_complete(NEW.interview_id);
    IF TG_OP = 'UPDATE' AND OLD.interview_id IS DISTINCT FROM NEW.interview_id THEN
      PERFORM assert_interview_blueprint_complete(OLD.interview_id);
    END IF;
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION reject_verification_for_deleting_user()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  candidate_identifiers text[] := ARRAY[NEW."identifier"];
  candidate_values text[] := ARRAY[NEW."value"];
  candidate_link_user_ids text[] := ARRAY[]::text[];
  matched_user_ids text[] := ARRAY[]::text[];
  account_owner record;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    candidate_identifiers := candidate_identifiers || OLD."identifier";
    candidate_values := candidate_values || OLD."value";
  END IF;

  SELECT coalesce(array_agg(DISTINCT candidate."link_user_id"), ARRAY[]::text[])
    INTO candidate_link_user_ids
    FROM (
      SELECT safe_verification_value_jsonb(candidate_value) #>> '{link,userId}'
        AS "link_user_id"
        FROM unnest(candidate_values) AS values_to_parse(candidate_value)
    ) AS candidate
   WHERE candidate."link_user_id" IS NOT NULL;

  FOR account_owner IN
    SELECT account_user."id", account_user."deletion_requested_at"
      FROM "user" AS account_user
     WHERE EXISTS (
       SELECT 1
         FROM unnest(candidate_identifiers, candidate_values)
           AS candidate("identifier", "value")
        WHERE candidate."identifier" = 'email-verification-otp-' || account_user."email"
           OR candidate."identifier" = 'sign-in-otp-' || account_user."email"
           OR candidate."identifier" = 'forget-password-otp-' || account_user."email"
           OR starts_with(
             candidate."identifier",
             'change-email-otp-' || account_user."email" || '-'
           )
           OR safe_verification_value_jsonb(candidate."value") #>> '{link,userId}'
             = account_user."id"
           OR safe_verification_value_jsonb(candidate."value") #>> '{link,email}'
             = account_user."email"
     )
     ORDER BY account_user."id"
     FOR UPDATE
  LOOP
    matched_user_ids := array_append(matched_user_ids, account_owner."id");
    IF account_owner."deletion_requested_at" IS NOT NULL THEN
      RAISE EXCEPTION 'Cannot write verification data for a deletion-marked account'
        USING
          ERRCODE = '23514',
          CONSTRAINT = 'verification_user_not_deleting_check';
    END IF;
  END LOOP;

  IF EXISTS (
    SELECT 1
      FROM unnest(candidate_link_user_ids) AS linked_owner("user_id")
     WHERE NOT linked_owner."user_id" = ANY(matched_user_ids)
  ) THEN
    RAISE EXCEPTION 'Cannot write account-link state without an active account'
      USING
        ERRCODE = '23514',
        CONSTRAINT = 'verification_user_not_deleting_check';
  END IF;

  RETURN NEW;
END;
$function$
